<template><view class="p"><jk-page-nav title="申请提现"/><view class="card"><text>提现金额</text><input v-model="amount" type="digit" placeholder="请输入金额"/><text>当前仅支持后台审核后的线下打款；最低提现额以后台业务配置为准</text></view><button @click="submit">提交申请</button></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{applyJkWithdraw}from'@/api/jk.js';export default{components:{JkPageNav},data(){return{amount:''}},methods:{submit(){if(!this.amount||Number(this.amount)<=0)return uni.showToast({title:'请输入有效金额',icon:'none'});applyJkWithdraw({amount:this.amount,requestNo:'WD'+Date.now(),payeeSnapshotJson:'{}'}).then(()=>{uni.showToast({title:'申请已提交'});setTimeout(()=>uni.navigateBack(),500)})}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{background:#fff;border-radius:18rpx;padding:28rpx;display:flex;flex-direction:column;gap:18rpx}.card text:last-child{font-size:24rpx;color:#78918b}input{font-size:40rpx}button{margin-top:30rpx;background:#20ad88;color:#fff}</style>